SELECT DISTINCT c.customer_first_name, c.customer_last_name
FROM Customers c
JOIN Products p ON c.town_city = p.product_color;

SELECT DISTINCT c.customer_first_name, c.customer_last_name
FROM Customers AS c
JOIN Products AS p ON p.product_color = c.town_city;

SELECT DISTINCT c.customer_first_name, c.customer_last_name
FROM Customers AS c
JOIN Products AS p ON c.town_city = p.product_color;

SELECT c.customer_first_name, c.customer_last_name
FROM Customers AS c
WHERE c.town_city IN (SELECT p.product_color FROM Products AS p);
